    cambiar = "B\u00e1jalo cuando una palabra de tu ecuaci\u00f3n de b\u00fasqueda aparezca en casi todos los textos y domine todos los resultados.",
    cambia = "El vocabulario de los modelos y de las redes de palabras; no cambia el recuento de documentos.",
    comprobar = "Consulta la lista de palabras que se retirar\u00edan. Una palabra muy extendida puede ser justo la que define tu tema.",
    ejemplo = "Si \u00abeducaci\u00f3n\u00bb est\u00e1 en el 95 % de los res\u00famenes porque estaba en la b\u00fasqueda, no distingue unos textos de otros; con un techo del 90 % se retira.",
    tecnica = "No existe un techo universal: depende de la pregunta y del tama\u00f1o del corpus. Se aplica sobre la frecuencia documental relativa."),
  max_terms = list(pregunta = "\u00bfCu\u00e1ntas palabras pueden usar los modelos?",
    empezar = "Conserva 1.000 si no tienes un motivo para cambiarlo. Es suficiente para la mayor\u00eda de corpus de res\u00famenes y mantiene los c\u00e1lculos r\u00e1pidos.",
    cambiar = "Red\u00facelo si el c\u00e1lculo tarda mucho o los resultados se llenan de palabras raras; aum\u00e9ntalo si el corpus es muy grande y variado.",
    cambia = "Cu\u00e1ntas palabras entran en los modelos. Solo act\u00faa cuando hay m\u00e1s palabras elegibles que este m\u00e1ximo.",
    comprobar = "Mira cu\u00e1ntas palabras quedan fuera y si alg\u00fan documento pierde todo su vocabulario. Si el m\u00e1ximo no recorta nada, el orden elegido tampoco importa.",
    ejemplo = "Si 1.800 palabras cumplen tus filtros y el m\u00e1ximo es 1.000, el criterio de orden decide cu\u00e1les 1.000 entran; si solo cumplen 600, entran las 600.",
    tecnica = "Se ordenan las palabras elegibles con el criterio de orden y se conservan las primeras. Las excluidas guardan el motivo \u00abL\u00edmite de vocabulario\u00bb."),
  term_order = list(pregunta = "Si hay m\u00e1s palabras que plazas, \u00bfcu\u00e1les deben entrar primero?",
    empezar = "Usa la frecuencia total si dudas: prioriza palabras muy usadas. Cambia solo si quieres favorecer palabras que distinguen unos textos de otros.",
    cambiar = "Elige TF-IDF si buscas vocabulario caracter\u00edstico de ciertos documentos; elige BM25 si hay textos de longitudes muy distintas.",
    cambia = "Qu\u00e9 palabras ocupan las plazas del m\u00e1ximo. No cambia los filtros de exclusi\u00f3n ni los documentos.",
